SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_dm_ht_control(
 id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
  target int(7) DEFAULT 0,
  result int(7) DEFAULT 0,
  target1 int(7) DEFAULT 0,
  result1 int(7) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_dm_ht_control WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_dm_ht_control 
(
SELECT
@id,p.check_hosp hospcode,p.check_vhid areacode
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543
,COUNT(DISTINCT IF(d.type_dx in(2,3),d.cid,NULL)) target
,COUNT(DISTINCT IF(d.type_dx in(2,3) AND d.control_dm IN(1) ,d.cid,NULL )) result
,COUNT(DISTINCT IF(d.type_dx in(1,3),d.cid,NULL)) target1
,COUNT(DISTINCT IF(d.type_dx in(1,3) AND d.control_ht IN(1) ,d.cid,NULL )) result1
FROM
t_dmht d 
INNER JOIN t_person_cid p ON d.cid=p.CID
WHERE d.cid IS NOT NULL  AND p.check_typearea IN(1,3) 
AND p.NATION IN(99) AND p.DISCHARGE IN(9)
AND substr(p.check_vhid,1,2) IN(@prov_c)
GROUP BY p.check_hosp,p.check_vhid
);
